  "claims": [
    {
      "claim": "Direct human absolute/systemic availability measurements for lipophilic basic amines with two aromatic rings and propylamine-type linkers—diphenhydramine (0.69), imipramine-N-oxide (~100%), urapidil (72–78%), donepezil (~100%), laquinimod (high), oxcarbazepine (89%), tiracizine (34%), moexipril (22%), and FK788 (55%)—support F ≥ 20% for the query.",
      "card_ids": ["C09", "C10", "C04", "C07", "C23", "C03", "C17", "C12", "C06"]
    },
    {
      "claim": "L3 oral exposure records for similar lipophilic basic amines show substantial systemic exposure after oral dosing: desipramine AUC0-∞ 516–655 ng·h/mL and Cmax ~18–21 ng/mL after 50 mg; imipramine AUC0-∞ 427 ng·h/mL; nortriptyline AUC0-∞ 258 ng·h/mL; fentanyl Cmax 645 pg/mL after 300 µg. These confirm oral absorption, though they lack IV comparators.",
      "card_ids": ["C95", "C80", "C77", "C91", "C113"]
    },
    {
      "claim": "L4 intestinal absorption and permeability records for close structural analogs are strongly supportive: imipramine is essentially 100% absorbed in humans (Fa 100%), desipramine is classified as intestinally absorbed and is a high-permeability internal standard (Caco-2 Papp 82.8×10^-6 cm/s; MDCKII 38.3×10^-6 cm/s), and amitriptyline, pheniramine, and diphenhydramine show high Caco-2 permeability. These support high intestinal absorption for the query's basic diamine scaffold.",
      "card_ids": ["C127", "C129", "C175", "C160", "C168", "C135", "C132", "C133", "C136", "C130", "C128", "C161", "C162", "C164", "C145", "C170", "C158"]
    },
    {
      "claim": "Low-F records for benazeprilat (<7%, dog 2.57%, cat 3.2%) and FK788 in rat (9.6%) come from polar acids/zwitterions or species-specific contexts and are not transferable to the lipophilic basic diamine query.",
      "card_ids": ["C38", "C50", "C32", "C45", "C48"]
    }
  ],
  "new_evidence_assessment": [
